CREATE TABLE users(id INTEGER PRIMARY KEY, username TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, role TEXT NOT NULL REFERENCES roles(code), specialty TEXT NOT NULL REFERENCES specialties(code), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), created_at TEXT NOT NULL);
CREATE TABLE roles(code TEXT PRIMARY KEY);
INSERT INTO roles VALUES('SUPERADMIN'),('SUPERVISOR'),('TECHNICIAN');
CREATE TABLE specialties(code TEXT PRIMARY KEY);
INSERT INTO specialties VALUES('MECANICA'),('ELECTRICA'),('GENERAL');
CREATE TABLE permissions(code TEXT PRIMARY KEY);
INSERT INTO permissions VALUES('incidents.manage'),('incidents.assigned'),('reports.review'),('users.manage'),('settings.manage'),('audit.view');
CREATE TABLE role_permissions(role TEXT REFERENCES roles(code), permission TEXT REFERENCES permissions(code), PRIMARY KEY(role,permission));
INSERT INTO role_permissions VALUES('SUPERADMIN','incidents.manage'),('SUPERADMIN','reports.review'),('SUPERADMIN','users.manage'),('SUPERADMIN','settings.manage'),('SUPERADMIN','audit.view'),('SUPERVISOR','incidents.manage'),('SUPERVISOR','reports.review'),('SUPERVISOR','audit.view'),('TECHNICIAN','incidents.assigned');
CREATE TABLE incidents(id INTEGER PRIMARY KEY, title TEXT NOT NULL CHECK(length(trim(title))>0), equipment TEXT NOT NULL, location TEXT NOT NULL, description TEXT NOT NULL, priority TEXT NOT NULL CHECK(priority IN('CRITICA','ALTA','MEDIA','BAJA')), specialty TEXT NOT NULL REFERENCES specialties(code), status TEXT NOT NULL DEFAULT 'PENDIENTE' CHECK(status IN('PENDIENTE','ASIGNADO','EN_PROCESO','EN_REVISION','COMPLETADO')), assigned_to INTEGER REFERENCES users(id), created_by INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, started_at TEXT, finished_at TEXT, draft TEXT NOT NULL DEFAULT '', submitted_version INTEGER REFERENCES report_versions(id), observation TEXT NOT NULL DEFAULT '', revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE incident_assignments(id INTEGER PRIMARY KEY, incident_id INTEGER NOT NULL REFERENCES incidents(id), technician_id INTEGER NOT NULL REFERENCES users(id), assigned_by INTEGER NOT NULL REFERENCES users(id), assigned_at TEXT NOT NULL, unassigned_at TEXT);
CREATE TABLE incident_status_history(id INTEGER PRIMARY KEY, incident_id INTEGER NOT NULL REFERENCES incidents(id), from_status TEXT, to_status TEXT NOT NULL, changed_by INTEGER NOT NULL REFERENCES users(id), reason TEXT NOT NULL, at TEXT NOT NULL);
CREATE TABLE attentions(id INTEGER PRIMARY KEY, incident_id INTEGER NOT NULL UNIQUE REFERENCES incidents(id), technician_id INTEGER NOT NULL REFERENCES users(id), started_at TEXT NOT NULL, finished_at TEXT);
CREATE TABLE reports(id INTEGER PRIMARY KEY, attention_id INTEGER NOT NULL UNIQUE REFERENCES attentions(id));
CREATE TABLE report_versions(id INTEGER PRIMARY KEY, report_id INTEGER NOT NULL REFERENCES reports(id), incident_id INTEGER NOT NULL REFERENCES incidents(id), version INTEGER NOT NULL, content TEXT NOT NULL, author_id INTEGER NOT NULL REFERENCES users(id), kind TEXT NOT NULL CHECK(kind IN('BORRADOR','ENVIADO')), origin TEXT NOT NULL DEFAULT 'MANUAL' CHECK(origin='MANUAL'), created_at TEXT NOT NULL, UNIQUE(incident_id,version));
CREATE TABLE report_reviews(id INTEGER PRIMARY KEY, incident_id INTEGER NOT NULL REFERENCES incidents(id), version_id INTEGER NOT NULL REFERENCES report_versions(id), reviewer_id INTEGER NOT NULL REFERENCES users(id), decision TEXT NOT NULL CHECK(decision IN('DEVUELTO','APROBADO')), comments TEXT NOT NULL, at TEXT NOT NULL);
CREATE TABLE audit_logs(id INTEGER PRIMARY KEY, incident_id INTEGER REFERENCES incidents(id), actor_id INTEGER NOT NULL REFERENCES users(id), action TEXT NOT NULL, detail TEXT NOT NULL, at TEXT NOT NULL);
CREATE TABLE app_settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT INTO app_settings VALUES('inactivity_minutes','15');
CREATE INDEX ix_incidents_assigned ON incidents(assigned_to,status);
CREATE INDEX ix_incidents_state ON incidents(status,priority,created_at);
CREATE INDEX ix_audit_incident ON audit_logs(incident_id,at);
